#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    int minimumPushes(std::string word) {
        std::vector<int> count(26, 0);
        for (char ch : word) count[ch - 'a']++;
        std::sort(count.rbegin(), count.rend());
        int ans = 0;
        for (int i = 0; i < 26; ++i) {
            if (count[i] == 0) break;
            ans += (i / 8 + 1) * count[i];
        }
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    public int minimumPushes(String word) {
        int[] count = new int[26];
        for (char ch : word.toCharArray()) count[ch - 'a']++;
        Arrays.sort(count);
        int ans = 0;
        for (int i = 0; i < 26; ++i) {
            int c = count[25 - i];
            if (c == 0) break;
            ans += (i / 8 + 1) * c;
        }
        return ans;
    }
}

var minimumPushes = function(word) {
    const count = new Array(26).fill(0);
    for (const ch of word) count[ch.charCodeAt(0) - 97]++;
    count.sort((a, b) => b - a);
    let ans = 0;
    for (let i = 0; i < 26; ++i) {
        if (count[i] === 0) break;
        ans += (Math.floor(i / 8) + 1) * count[i];
    }
    return ans;
};
